INSERT INTO dump_descriptions (base_key, description) VALUES ('flyingdickcats_polaris_english', 'English text translation for Flying Dickcat’s Polaris ice weapon and overclock; the author says the translation used Google Translate and guesswork.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
